import{_ as t,o as r,c as a,ak as d}from"./chunks/framework.B8jO0odJ.js";const h=JSON.parse('{"title":"Chainy product acceptance checklist","description":"Current requirements, October 12, 2026. The baseline owns scope; the GDD owns gameplay. These TD-R IDs distinguish the replacement plan from historical CH-R requirements.","frontmatter":{"title":"Chainy product acceptance checklist","description":"Current requirements, October 12, 2026. The baseline owns scope; the GDD owns gameplay. These TD-R IDs distinguish the replacement plan from historical CH-R requirements.","source":"docs/requirements/product-requirements.md","category":"Requirements","sourceUpdated":"2026-10-12T21:55:56+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/requirements/product-requirements.md","filePath":"content/docs/requirements/product-requirements.md"}'),n={name:"content/docs/requirements/product-requirements.md"};function c(i,e,s,o,l,p){return r(),a("div",null,[...e[0]||(e[0]=[d('<div><h1 id="chainy-product-acceptance-checklist">Chainy product acceptance checklist<a class="header-anchor" href="#chainy-product-acceptance-checklist" aria-label="Link to this section">​</a></h1><p>Current requirements, October 12, 2026. The <a href="/Chainy-Docs/content/docs/project-baseline.html">baseline</a> owns scope; the <a href="/Chainy-Docs/content/docs/game-design.html">GDD</a> owns gameplay. These TD-R IDs distinguish the replacement plan from historical CH-R requirements.</p><table><thead><tr><th>ID</th><th>Required outcome</th><th>Evidence for acceptance</th><th>Tasks</th></tr></thead><tbody><tr><td>TD-R01</td><td>Offline Android game</td><td>Installed build opens and completes a learning activity without internet</td><td>CH-03, CH-14</td></tr><tr><td>TD-R02</td><td>Explorable learning levels and interactions</td><td>Movement, collision, dialogue/interaction and scene transition work on the device</td><td>CH-05, CH-13</td></tr><tr><td>TD-R03</td><td>Quiz</td><td>Agreed answers, scores, attempts and finish rules work; result saves and reloads</td><td>CH-06</td></tr><tr><td>TD-R04</td><td>Wordle</td><td>Dictionary, input, repeated-letter feedback, win/loss and retry follow approved rules</td><td>CH-08</td></tr><tr><td>TD-R05</td><td>BlockMatch</td><td>Matches, cascades, objectives and end/no-move handling follow approved rules</td><td>CH-07</td></tr><tr><td>TD-R06</td><td>Learning content and usable UI</td><td>Each mode has an objective, accurate content, instructions and explanation; readable touch UI</td><td>CH-02, CH-09, CH-10, CH-26</td></tr><tr><td>TD-R07</td><td>Local profile and progress</td><td>Separate profiles; reliable save/reload; no duplicate counting on save retry</td><td>CH-04, CH-06, CH-14</td></tr><tr><td>TD-R08</td><td>Teacher evidence collection</td><td>Approved records can be collected without loss or duplicate counting</td><td>CH-11, CH-12, CH-15</td></tr><tr><td>TD-R09</td><td>Tested update/recovery</td><td>Agreed signed update and recovery procedure preserves tested records</td><td>CH-14, CH-20</td></tr><tr><td>TD-R10</td><td>School deliverables</td><td>Functional build, actual evaluation/site evidence, complete manuscript and rehearsal</td><td>CH-01, CH-12, CH-15–25</td></tr></tbody></table><p>TD-R06 retains foundational Web3, Blockchain and AI content without requiring the withdrawn simulation/classifier/agent mechanics. Topic and level counts are not fixed by the supplied technical design.</p><p>The user replaced the previous gameplay requirements. Historical CH-R01–12 remain traceable in the <a href="/Chainy-Docs/content/docs/archive/pre-2026-10-12/docs/requirements/product-requirements.html">earlier requirements</a>, not additional acceptance criteria.</p><p>All checks need an actual result and artifact link. A written specification, an open issue, or a tech-lead status report is not equivalent to a passed device test.</p></div>',1)])])}const m=t(n,[["render",c]]);export{h as __pageData,m as default};
